import (
	"context"
	"sync"
)

type Job func(ctx context.Context) error

type WorkerPool struct {
	maxWorkers int
	jobs       chan Job
	wg         sync.WaitGroup
}

func NewWorkerPool(maxWorkers int, queueCap int) *WorkerPool {
	return &WorkerPool{
		maxWorkers: maxWorkers,
		jobs:       make(chan Job, queueCap),
	}
}

func (p *WorkerPool) Start(ctx context.Context) {
	for i := 0; i < p.maxWorkers; i++ {
		p.wg.Add(1)
		go func() {
			defer p.wg.Done()
			for {
				select {
				case <-ctx.Done():
					return
				case job, ok := <-p.jobs:
					if !ok {
						return
					}
					_ = job(ctx)
				}
			}
		}()
	}
}

func (p *WorkerPool) Submit(job Job) {
	p.jobs <- job
}

func (p *WorkerPool) Stop() {
	close(p.jobs)
	p.wg.Wait()
}

use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use std::time::{Duration, Instant};

#[derive(Clone)]
struct CacheEntry<V> {
    value: V,
    expires_at: Instant,
}

#[derive(Clone)]
pub struct TtlCache<K, V> {
    store: Arc<RwLock<HashMap<K, CacheEntry<V>>>>,
}

impl<K: std::hash::Hash + Eq + Clone, V: Clone> TtlCache<K, V> {
    pub fn new() -> Self {
        Self {
            store: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    pub fn set(&self, key: K, value: V, ttl: Duration) {
        let entry = CacheEntry {
            value,
            expires_at: Instant::now() + ttl,
        };
        if let Ok(mut lock) = self.store.write() {
            lock.insert(key, entry);
        }
    }

    pub fn get(&self, key: &K) -> Option<V> {
        let lock = self.store.read().ok()?;
        let entry = lock.get(key)?;
        if Instant::now() > entry.expires_at {
            None
        } else {
            Some(entry.value.clone())
        }
    }
}

